<template>
  <el-card shadow="never">
    <template #header><div class="business-finance-heading"><strong>{{label}}</strong><div><el-button @click="open('statement')">对账单</el-button><el-button @click="open('invoice')">发票</el-button><el-button @click="open('special')">特殊结算</el-button><el-button @click="ledgerVisible=true">查账追账</el-button><TableColumnSettings v-model="selectedKeys" :settings-key="module+'-finance'" :columns="columns" @reset="resetColumns" /></div></div></template>
    <AppForm :model="filters" inline data-auto-draft="off" @submit.prevent="search"><el-form-item label="关键词"><el-input v-model="filters.keyword" placeholder="订单号、项目名称、客户名称" clearable @input="queueSearch" @keyup.enter="search" /></el-form-item><el-form-item label="客户经理"><el-select v-model="filters.manager" @change="search"><el-option label="本人" value="self" /><el-option label="全部客户经理" value="all" /><el-option label="指定客户经理" value="name" /></el-select><FinanceManagerNameSelect v-if="filters.manager==='name'" v-model="filters.name" @change="search" /></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></AppForm>
    <el-alert v-if="error" type="error" :title="error" :closable="false" />
    <p>{{module==='annotation'?'客户单价从标注项目管理带出；客户单价细化与验收工作量可单独维护。':'服务费从招聘项目管理带出；年薪比例、月薪倍数按薪酬基数计算，再乘实际验收人数。'}} 缺少单价或验收工作量时小计显示待填写。</p>
    <el-table :data="pagedRows" border v-loading="loading" max-height="650" row-key="id">
      <el-table-column type="index" label="序号" width="65" />
      <el-table-column v-for="column in visibleColumns" :key="column.key" :prop="column.key" :min-width="column.width||170">
        <template #header><ConfiguredColumnHeaderFilter v-model="columnFilters[column.key]" :definition="{key:column.key,label:column.label,type:'text'}" @update:model-value="page=1" /></template>
        <template #default="{row}"><template v-if="column.key==='pricing'"><div v-for="(price,index) in row.payload.rates" :key="index">{{price.currency}} {{price.amount??'待填'}} / {{price.unit}}</div><el-button link type="primary" :disabled="!canWrite" @click="edit(row)">编辑单价／工作量</el-button></template><template v-else-if="column.key==='quantity'"><div v-for="(price,index) in row.payload.rates" :key="index">{{price.quantity??'待填写'}} {{price.unit}}</div></template><template v-else>{{cell(row,column.key)}}</template></template>
      </el-table-column>
      <el-table-column label="详情" fixed="right" width="100"><template #default="{row}"><el-popover placement="left" :width="760" trigger="click" :title="row.project_name+' · 财务详情'"><template #reference><el-button link>查看详情</el-button></template><div class="business-finance-details"><el-descriptions :column="2" border size="small"><el-descriptions-item v-for="column in columns" :key="column.key" :label="column.label">{{cell(row,column.key)||'-'}}</el-descriptions-item></el-descriptions></div></el-popover></template></el-table-column>
      <el-table-column label="操作" fixed="right" width="110"><template #default="{row}"><el-dropdown @command="command=>open(command,row)"><el-button link type="primary">操作 ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">价格与收费</el-dropdown-item><el-dropdown-item command="statement">对账单</el-dropdown-item><el-dropdown-item command="invoice">发票／开票需求</el-dropdown-item><el-dropdown-item command="special">特殊结算</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
    </el-table>
    <p>筛选后项目金额小计：{{money(sum(filteredRows,'billing_totals'))}}；已付小计：{{money(sum(filteredRows,'received_totals'))}}；实付－应付差异：{{money(sum(filteredRows,'payment_difference'))}}</p>
    <el-pagination v-model:current-page="page" :page-size="20" :total="filteredRows.length" layout="total, prev, pager, next" />
    <InterpretationStatementDialog v-if="statementVisible" v-model="statementVisible" :module="module" :projects="documentProjects" :query="query" :initial-mode="special?'special':undefined" />
    <BusinessFinanceLedgerDialog v-if="ledgerVisible" v-model="ledgerVisible" :module="module" :query="query" />
    <DraggableFormDialog v-model="invoicePicker" title="选择开票项目／客户" width="min(760px, calc(100vw - 32px))" append-to-body><el-select v-model="invoiceId" filterable style="width:100%"><el-option v-for="row in filteredRows" :key="row.id" :value="row.id" :label="row.client_name+' · '+row.order_no+' · '+row.project_name" /></el-select><template #footer><el-button @click="invoicePicker=false">取消</el-button><el-button type="primary" :disabled="!invoiceId" @click="invoicePicker=false;invoiceVisible=true">打开发票窗口</el-button></template></DraggableFormDialog>
    <InterpretationInvoiceDialog v-if="invoiceVisible" v-model="invoiceVisible" :module="module" :project-id="invoiceId" :can-write="canWrite" @saved="load" />
    <DraggableFormDialog v-model="editVisible" class="business-finance-editor" width="min(1150px, calc(100vw - 32px))" top="4vh" append-to-body :close-on-click-modal="false" :before-close="beforeEditClose">
      <template #header><DialogFieldSearchHeader ref="fieldSearchRef" v-model="fieldSearchKeyword" :title="label+'价格与收费 · '+(editing?.order_no||'')" :fetch-suggestions="fetchFieldSuggestions" @select="locateDialogField" @clear="clearFieldSearch" /></template>
      <div ref="editBody"><AppForm v-if="editing" ref="editForm" :model="draft" label-position="top" :disabled="!canWrite||saving" data-auto-draft="off"><el-descriptions :column="2" border size="small"><el-descriptions-item label="订单号">{{editing.order_no}}</el-descriptions-item><el-descriptions-item label="项目名称">{{editing.project_name}}</el-descriptions-item><el-descriptions-item label="项目客户报价">{{sourcePrice(editing)}}</el-descriptions-item><el-descriptions-item v-if="module==='recruitment'" label="招聘服务费类型">{{feeLabels[editing.service_fee_type]||'未设置'}} {{editing.service_fee_rate?editing.service_fee_rate+'%':''}} {{editing.service_fee_multiplier?editing.service_fee_multiplier+'倍':''}}</el-descriptions-item></el-descriptions>
        <div class="business-finance-grid"><el-form-item label="结算模式"><el-select v-model="draft.settlement.payment_method"><el-option v-for="(text,key) in modes" :key="key" :value="key" :label="text" :disabled="key==='sub_client'&&!editing.sub_client_id" /></el-select></el-form-item><el-form-item label="账单月份"><el-date-picker v-model="draft.settlement.billing_month" type="month" value-format="YYYY-MM" /></el-form-item><el-form-item label="计价税口径"><el-select v-model="draft.settlement.tax_basis"><el-option label="税口径未确认" value="legacy" /><el-option label="不含税" value="excl_tax" /><el-option label="含税" value="incl_tax" /></el-select></el-form-item><el-form-item label="单据需求"><el-checkbox v-model="draft.settlement.invoice_required">需发票</el-checkbox><span>对账单按结算模式制作</span></el-form-item></div>
        <el-form-item v-if="module==='recruitment'&&['annual_salary_rate','monthly_salary_multiple'].includes(editing.service_fee_type)" :label="editing.service_fee_type==='annual_salary_rate'?'年薪基数':'月薪基数'"><el-input-number v-model="draft.salary_basis" :min="0" :precision="2" :controls="false" /></el-form-item>
        <section v-for="(price,index) in draft.rates" :key="index" class="business-finance-grid"><el-form-item label="收费明细"><el-input v-model="price.direction" maxlength="500" /></el-form-item><el-form-item label="货币"><el-select v-model="price.currency" filterable><el-option v-for="code in currencies" :key="code" :value="code" /></el-select></el-form-item><el-form-item label="客户单价细化金额"><ReadonlyField v-if="module==='recruitment'&&['annual_salary_rate','monthly_salary_multiple'].includes(editing.service_fee_type)" :model-value="calculatedUnit" source="auto" /><el-input-number v-else v-model="price.amount" :min="0" :precision="6" :controls="false" /></el-form-item><el-form-item label="单位"><el-select v-model="price.unit" filterable allow-create><el-option v-for="unit in units" :key="unit" :value="unit" /></el-select></el-form-item><el-form-item :label="module==='recruitment'?'验收人数':'验收工作量'"><el-input-number v-model="price.quantity" :min="0" :precision="4" :controls="false" /></el-form-item><el-form-item label="小计"><ReadonlyField :model-value="lineSubtotal(price)" source="auto" /></el-form-item><el-button link type="danger" @click="draft.rates.splice(index,1)">移除明细</el-button></section>
        <el-button :disabled="draft.rates.length>=100" @click="draft.rates.push({direction:'收费明细',currency:'CNY',amount:null,quantity:null,unit:module==='recruitment'?'人':'个'})">新增收费明细</el-button>
        <el-form-item label="客户说明"><el-input v-model="draft.settlement.customer_explanation" type="textarea" maxlength="5000" /></el-form-item><el-form-item label="内部说明"><el-input v-model="draft.explanation" type="textarea" maxlength="5000" /></el-form-item><InterpretationPaymentFields v-model="draft" :amounts="draftTotals" />
      </AppForm></div><template #footer><el-button :disabled="saving" @click="closeEdit">取消</el-button><el-button v-if="canWrite" type="primary" :loading="saving" @click="save">保存并记录</el-button></template>
    </DraggableFormDialog>
  </el-card>
</template>
<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useRoute} from 'vue-router'
import api from '@/api'
import {hasPermission} from '@/utils/permission'
import {getLocalizedErrorMessage} from '@/utils/errorMessages'
import {matchesSearch} from '@/utils/searchMatching'
import {quotationLineCents,quotationMoney} from '@/utils/quotation'
import {translationSettlementModeLabels as modes} from '@/utils/settlementModes'
import {interpretationCurrencies as currencies} from '@/utils/interpretationCustomerFinance'
import {useTableColumns} from '@/composables/useTableColumns'
import {useDialogFieldSearch} from '@/composables/useDialogFieldSearch'
import TableColumnSettings from '@/components/common/TableColumnSettings.vue'
import ConfiguredColumnHeaderFilter from '@/components/common/ConfiguredColumnHeaderFilter.vue'
import FinanceManagerNameSelect from '@/components/common/FinanceManagerNameSelect.vue'
import InterpretationStatementDialog from '@/components/common/InterpretationStatementDialog.vue'
import InterpretationInvoiceDialog from '@/components/common/InterpretationInvoiceDialog.vue'
import InterpretationPaymentFields from '@/components/common/InterpretationPaymentFields.vue'
import BusinessFinanceLedgerDialog from '@/components/common/BusinessFinanceLedgerDialog.vue'
import DialogFieldSearchHeader from '@/components/common/DialogFieldSearchHeader.vue'
import ReadonlyField from '@/components/common/ReadonlyField.vue'
const route=useRoute(),module=computed(()=>route.params.module),label=computed(()=>module.value==='annotation'?'标注':'招聘'),canWrite=hasPermission('projects:write')
const filters=reactive({keyword:'',manager:'self',name:''}),rows=ref([]),page=ref(1),columnFilters=reactive({}),loading=ref(false),error=ref('')
const columns=[{key:'order_no',label:'订单号'},{key:'project_name',label:'项目名称',width:250},{key:'client_name',label:'客户名称'},{key:'client_manager_name',label:'客户经理'},{key:'source_price',label:'客户单价（项目管理）',width:220},{key:'pricing',label:'客户单价细化',width:220},{key:'quantity',label:'验收工作量'},{key:'billing_totals',label:'小计／项目金额'},{key:'settlement_mode',label:'结算模式'},{key:'billing_month',label:'账单月份'},{key:'received_totals',label:'实际付款累计'},{key:'payment_difference',label:'实付－应付差异'},{key:'invoice',label:'发票需求／状态'}]
const {selectedKeys,isVisible,reset:resetColumns}=useTableColumns(module.value+'-finance',columns,['order_no','project_name','client_name','source_price','pricing','quantity','billing_totals'])
const visibleColumns=computed(()=>columns.filter(row=>isVisible(row.key)))
const units=['个','条','份','页','字','字数','次','人','秒','分钟','小时','天','月','周','项','其他']
const feeLabels={fixed:'固定金额',annual_salary_rate:'年薪比例',monthly_salary_multiple:'月薪倍数',other:'其他'}
const query=computed(()=>({only_mine:filters.manager==='self',client_manager:filters.manager==='name'?filters.name:undefined}))
function sourcePrice(row){return row.module==='annotation'?(row.source_price?.prices||[]).map(price=>`${price.currency} ${price.amount}/${price.unit||'未填单位'}`).join('；'):[feeLabels[row.service_fee_type],row.source_price?.legacy_amount,row.service_fee_rate?row.service_fee_rate+'%':'',row.service_fee_multiplier?row.service_fee_multiplier+'倍':''].filter(Boolean).join(' ')}
const money=value=>Object.entries(value||{}).map(([code,amount])=>code+' '+amount).join(' / ')||'待填写'
function cell(row,key){if(key==='source_price')return sourcePrice(row);if(['billing_totals','received_totals','payment_difference'].includes(key))return money(row[key]);if(key==='pricing')return row.payload.rates.map(price=>`${price.currency} ${price.amount??'待填'}/${price.unit}`).join('；');if(key==='quantity')return row.payload.rates.map(price=>(price.quantity??'待填')+' '+price.unit).join('；');if(key==='settlement_mode')return modes[row[key]];if(key==='invoice')return (row.payload.settlement.invoice_required?'需发票':'无需发票')+' / '+({issued:'已开票',partial:'部分开票'}[row.payload.invoice?.invoice_status]||'未开票');return row[key]||'-'}
const filteredRows=computed(()=>rows.value.filter(row=>columns.every(column=>matchesSearch(cell(row,column.key),columnFilters[column.key]))))
const pagedRows=computed(()=>filteredRows.value.slice((page.value-1)*20,page.value*20))
function sum(items,key){const values={};for(const row of items)for(const [code,amount] of Object.entries(row[key]||{})){const cents=quotationLineCents({quantity:1,unit_price:amount},6);if(cents!=null)values[code]=(values[code]||0n)+cents}return Object.fromEntries(Object.entries(values).map(([code,cents])=>[code,quotationMoney(cents)]))}
let controller,timer,seq=0
async function load(){const number=++seq;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const collected=[];let skip=0,total=0;do{const data=await api.get(`/business-finance/${module.value}/page`,{params:{...query.value,keyword:filters.keyword,skip,limit:1000},signal:controller.signal});collected.push(...data.items);total=data.total;skip+=1000}while(skip<total&&number===seq);if(number===seq)rows.value=collected}catch(e){if(number===seq&&e.code!=='ERR_CANCELED')error.value=getLocalizedErrorMessage(e,'财务加载失败')}finally{if(number===seq)loading.value=false}}
function search(){clearTimeout(timer);page.value=1;void load()}
function queueSearch(){clearTimeout(timer);controller?.abort();seq++;if(!filters.keyword.trim())search();else timer=setTimeout(search,400)}
function reset(){Object.assign(filters,{keyword:'',manager:'self',name:''});for(const key of Object.keys(columnFilters))delete columnFilters[key];search()}
const statementVisible=ref(false),special=ref(false),ledgerVisible=ref(false),invoiceVisible=ref(false),invoicePicker=ref(false),invoiceId=ref(''),actionRow=ref(null),documentProjects=computed(()=>actionRow.value?[actionRow.value]:filteredRows.value)
function open(action,row=null){actionRow.value=row;if(action==='edit')return edit(row);if(action==='invoice'){invoiceId.value=row?.id||'';if(row)invoiceVisible.value=true;else invoicePicker.value=true;return}special.value=action==='special';statementVisible.value=true}
const editing=ref(null),editVisible=ref(false),draft=ref({}),editBody=ref(),editForm=ref(),saving=ref(false);let baseline=''
const {fieldSearchRef,fieldSearchKeyword,fetchFieldSuggestions,locateDialogField,clearFieldSearch}=useDialogFieldSearch(editBody)
function edit(row){editing.value=row;draft.value=JSON.parse(JSON.stringify(row.payload));for(const price of draft.value.rates){price.amount=price.amount==null?undefined:Number(price.amount);price.quantity=price.quantity==null?undefined:Number(price.quantity)}draft.value.salary_basis=draft.value.salary_basis==null?undefined:Number(draft.value.salary_basis);draft.value.settlement.payments=draft.value.settlement.payments.map(payment=>({...payment,amount:Number(payment.amount)}));draft.value.fixed_totals=[];draft.value.adjusted_totals=[];draft.value.has_overtime=false;baseline=JSON.stringify(draft.value);clearFieldSearch();editVisible.value=true}
const calculatedUnit=computed(()=>{if(!editing.value||draft.value.salary_basis==null)return '待填写薪酬基数';const value=Number(draft.value.salary_basis)*(editing.value.service_fee_type==='annual_salary_rate'?Number(editing.value.service_fee_rate)/100:Number(editing.value.service_fee_multiplier));return Number.isFinite(value)?value:'待填写比例／倍数'})
const draftTotals=computed(()=>{const totals={},missing=new Set();for(const price of draft.value.rates||[]){const amount=module.value==='recruitment'&&['annual_salary_rate','monthly_salary_multiple'].includes(editing.value?.service_fee_type)?calculatedUnit.value:price.amount;const cents=quotationLineCents({quantity:price.quantity,unit_price:amount},6);if(cents==null)missing.add(price.currency);else totals[price.currency]=(totals[price.currency]||0n)+cents}return Object.fromEntries(Object.entries(totals).filter(([code])=>!missing.has(code)).map(([code,amount])=>[code,quotationMoney(amount)]))})
function lineSubtotal(price){const amount=module.value==='recruitment'&&['annual_salary_rate','monthly_salary_multiple'].includes(editing.value?.service_fee_type)?calculatedUnit.value:price.amount;const cents=quotationLineCents({quantity:price.quantity,unit_price:amount},6);return cents==null?'待填写':price.currency+' '+quotationMoney(cents)}
async function allowClose(){if(saving.value)return false;if(JSON.stringify(draft.value)===baseline)return true;try{await ElMessageBox.confirm('收费修改未保存，是否放弃？','确认关闭');return true}catch{return false}}
async function closeEdit(){if(await allowClose())editVisible.value=false}
async function beforeEditClose(done){if(await allowClose())done()}
async function save(){if(!await editForm.value.validate().catch(()=>false))return;saving.value=true;try{const fields=['rates','settlement','settlement_adjustments','explanation','salary_basis'];const payload=Object.fromEntries(fields.map(key=>[key,draft.value[key]]));payload.rates=payload.rates.map(price=>({...price,amount:price.amount??null,quantity:price.quantity??null}));await api.put(`/business-finance/${module.value}/project/${editing.value.id}`,{revision:editing.value.revision,...payload});editVisible.value=false;ElMessage.success('财务已保存并记录');await load()}catch(e){ElMessage.error(getLocalizedErrorMessage(e,'财务保存失败'))}finally{saving.value=false}}
watch(()=>module.value,()=>search(),{immediate:true});onBeforeUnmount(()=>{controller?.abort();clearTimeout(timer)})
</script>
<style scoped>.business-finance-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.business-finance-heading>div{display:flex;gap:8px;flex-wrap:wrap}.business-finance-heading .el-button+.el-button{margin-left:0}.business-finance-details{max-height:560px;overflow-y:auto;white-space:pre-wrap;overflow-wrap:anywhere}.business-finance-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:10px;margin:12px 0;padding:10px;border:1px solid var(--el-border-color)}p{font-size:13px;color:var(--el-text-color-secondary)}</style>
<style>.business-finance-editor{display:flex;flex-direction:column;max-height:90vh;overflow:hidden}.business-finance-editor>.el-dialog__body{min-height:0;overflow-y:auto;flex:1}.business-finance-editor>.el-dialog__header,.business-finance-editor>.el-dialog__footer{flex:none}.business-finance-editor>.el-dialog__footer{border-top:1px solid var(--el-border-color);background:var(--el-fill-color-light)}</style>
